/// DSPi Link (crates/dspi-link): frame kinds (`KIND_*`, spec 8), CMD response
/// statuses (`STATUS_*`, spec 8.1), the default port and the protocol version.
public enum LinkConstants {
    public static let KIND_CMD_REQUEST: UInt8 = 0x01
    public static let KIND_CMD_RESPONSE: UInt8 = 0x81
    public static let KIND_NOTIFY: UInt8 = 0x02
    public static let KIND_POLL: UInt8 = 0x03
    public static let KIND_FWDATA: UInt8 = 0x04
    public static let KIND_FWDATA_ACK: UInt8 = 0x84
    public static let KIND_RESYNC: UInt8 = 0x05
    public static let STATUS_OK: UInt8 = 0x00
    public static let STATUS_BUSY: UInt8 = 0x01
    public static let STATUS_ERROR: UInt8 = 0x02
    public static let STATUS_BLOCKED: UInt8 = 0x03
    public static let STATUS_BULK_LOCKED: UInt8 = 0x04
    public static let STATUS_CRC_ERROR: UInt8 = 0x05
    public static let STATUS_OVERSIZE: UInt8 = 0x06
    public static let STATUS_FRAME_ERROR: UInt8 = 0x07
    public static let STATUS_NO_DEVICE: UInt8 = 0x80
    public static let STATUS_DENIED: UInt8 = 0x81
    public static let STATUS_TIMEOUT: UInt8 = 0x82
    public static let STATUS_TOO_LARGE: UInt8 = 0x83
    public static let STATUS_RATE_LIMITED: UInt8 = 0x84
    public static let STATUS_LOCKED: UInt8 = 0x85
    public static let STATUS_UNSUPPORTED: UInt8 = 0x86
    public static let STATUS_BAD_FRAME: UInt8 = 0x87
    /// Default hub port: decimal of the USB VID 0x2E8B (spec 3.1).
    public static let DEFAULT_PORT: UInt16 = 11915
    /// The protocol this client speaks (spec 1.2; 1.1 hubs are compatible, 13.1).
    public static let PROTO_MAJOR: UInt32 = 1
    public static let PROTO_MINOR: UInt32 = 2
}
